package tech.qiantong.qdata.acceptance;

import org.junit.jupiter.api.*;
import org.junit.jupiter.api.condition.EnabledIfEnvironmentVariable;
import org.springframework.jdbc.core.JdbcTemplate;
import org.springframework.jdbc.datasource.*;
import org.springframework.security.authentication.UsernamePasswordAuthenticationToken;
import org.springframework.security.core.context.SecurityContextHolder;
import org.springframework.security.access.AccessDeniedException;
import org.springframework.test.util.ReflectionTestUtils;
import org.springframework.transaction.support.TransactionTemplate;
import tech.qiantong.qdata.common.core.domain.entity.SysUser;
import tech.qiantong.qdata.common.core.domain.model.LoginUser;
import tech.qiantong.qdata.module.att.controller.admin.project.vo.AttProjectSaveReqVO;
import tech.qiantong.qdata.module.att.service.project.*;
import tech.qiantong.qdata.security.web.service.ProjectPermissionService;
import tech.qiantong.qdata.redis.service.IRedisService;
import tech.qiantong.qdata.api.ds.api.project.*;
import tech.qiantong.qdata.api.ds.api.service.project.IDsProjectService;
import java.util.*;
import java.util.concurrent.atomic.AtomicLong;
import static org.junit.jupiter.api.Assertions.*;
import static org.mockito.Mockito.*;
import static org.mockito.ArgumentMatchers.*;

@EnabledIfEnvironmentVariable(named="QDATA_NAMESPACE_INTEGRATION",matches="true")
class LocalProjectLifecycleIntegrationTest {
    SingleConnectionDataSource fixture;JdbcTemplate jdbc;TransactionTemplate tx;
    ProjectPermissionService permissions;ProjectAuthority authority;ProjectLifecycleService lifecycle;IRedisService sequence;IDsProjectService external;
    @BeforeEach void setup(){
        String url=System.getenv("QDATA_PROJECT_LIFECYCLE_URL");assertNotNull(url);assertTrue(url.contains("/qdata_project_lifecycle_"));fixture=new SingleConnectionDataSource(url,"root",System.getenv("QDATA_NAMESPACE_PASSWORD"),true);jdbc=new JdbcTemplate(fixture);tx=new TransactionTemplate(new DataSourceTransactionManager(fixture));permissions=new ProjectPermissionService(jdbc);authority=new ProjectAuthority(jdbc,permissions);sequence=mock(IRedisService.class);external=mock(IDsProjectService.class);var codes=new AtomicLong(1789400000000000L);when(sequence.nextSequence(anyString(),anyLong())).thenAnswer(invocation->codes.incrementAndGet());lifecycle=new ProjectLifecycleService(jdbc,sequence,external,permissions,authority);actor(925);
    }
    @AfterEach void finish(){SecurityContextHolder.clearContext();fixture.destroy();}
    void actor(long id){var user=new SysUser();user.setUserId(id);user.setUserName("project-lifecycle-fixture");user.setRoles(List.of());SecurityContextHolder.getContext().setAuthentication(new UsernamePasswordAuthenticationToken(new LoginUser(id,null,user,Set.of("*:*:*")),null,List.of()));}
    AttProjectSaveReqVO request(){var value=new AttProjectSaveReqVO();value.setName("local-project-fixture");value.setManagerId(925L);value.setDescription("retained fixture transaction");return value;}
    DsProjectRespDTO externalResponse(int code){var result=new DsProjectRespDTO();result.setCode(code);var data=result.new Data();data.setCode(900900L);result.setData(data);return result;}
    @Test void localCreatePersistsManagerAndScopedRoleWithoutExternalScheduler(){tx.executeWithoutResult(status->{long id=lifecycle.create(request());assertEquals("QUARTZ",jdbc.queryForObject("SELECT scheduler_type FROM att_project WHERE id=?",String.class,id));assertEquals(1,jdbc.queryForObject("SELECT COUNT(*) FROM att_project_user_rel WHERE project_id=? AND user_id=925 AND valid_flag='1'",Integer.class,id));assertEquals(1,jdbc.queryForObject("SELECT COUNT(*) FROM system_user_role ur JOIN system_role r ON r.role_id=ur.role_id WHERE ur.user_id=925 AND r.project_id=? AND r.role_key='gly'",Integer.class,id));verifyNoInteractions(external);status.setRollbackOnly();});}
    @Test void fallbackManagerRoleContainsNoGlobalSystemPermissions(){tx.executeWithoutResult(status->{long id=lifecycle.create(request());var perms=jdbc.queryForList("SELECT m.perms FROM system_menu m JOIN system_role_menu rm ON rm.menu_id=m.menu_id JOIN system_role r ON r.role_id=rm.role_id WHERE r.project_id=? AND m.perms IS NOT NULL",String.class,id);assertFalse(perms.isEmpty());assertTrue(perms.stream().allMatch(p->p.isBlank() || p.startsWith("att:project:") || p.startsWith("att:projectUserRel:")));assertFalse(perms.contains("att:project:add"));status.setRollbackOnly();});}
    @Test void defaultManagerAndServerCodeIgnoreForgedMetadata(){tx.executeWithoutResult(status->{var input=request();input.setManagerId(null);input.setCode("foreign-project-code");input.setCreatorId(926L);long id=lifecycle.create(input);var row=jdbc.queryForMap("SELECT manager_id,creator_id,code FROM att_project WHERE id=?",id);assertEquals(925L,((Number)row.get("manager_id")).longValue());assertEquals(925L,((Number)row.get("creator_id")).longValue());assertNotEquals("foreign-project-code",row.get("code"));status.setRollbackOnly();});}
    @Test void blankNameAndInactiveManagerStopBeforeScheduling(){var input=request();input.setName("  ");assertThrows(IllegalArgumentException.class,()->lifecycle.create(input));input.setName("valid");input.setManagerId(-10L);assertThrows(IllegalArgumentException.class,()->lifecycle.create(input));verifyNoInteractions(sequence,external);}
    @Test void projectScopedRoleCannotGrantPlatformProjectCreation(){actor(926);assertThrows(AccessDeniedException.class,()->lifecycle.create(request()));verifyNoInteractions(sequence,external);}
    @Test void localEditKeepsCodeAndAvoidsExternalCalls(){tx.executeWithoutResult(status->{long id=lifecycle.create(request());String code=jdbc.queryForObject("SELECT code FROM att_project WHERE id=?",String.class,id);var input=request();input.setId(id);input.setName("updated local project");assertEquals(1,lifecycle.update(input));assertEquals(code,jdbc.queryForObject("SELECT code FROM att_project WHERE id=?",String.class,id));verify(sequence,times(1)).nextSequence(anyString(),anyLong());verifyNoInteractions(external);status.setRollbackOnly();});}
    @Test void managerTransferKeepsPriorMembersAndEnsuresNewManagerAuthority(){tx.executeWithoutResult(status->{long id=lifecycle.create(request());var input=request();input.setId(id);input.setManagerId(926L);lifecycle.update(input);assertEquals(2,jdbc.queryForObject("SELECT COUNT(*) FROM att_project_user_rel WHERE project_id=? AND valid_flag='1' AND del_flag='0'",Integer.class,id));actor(926);assertTrue(authority.canEdit(id));status.setRollbackOnly();});}
    @Test void inactiveExistingMemberIsRestoredWithoutDuplicateMembership(){tx.executeWithoutResult(status->{long id=lifecycle.create(request());jdbc.update("INSERT INTO att_project_user_rel(project_id,user_id,valid_flag,del_flag) VALUES(?,926,'0','0')",id);var input=request();input.setId(id);input.setManagerId(926L);lifecycle.update(input);assertEquals(1,jdbc.queryForObject("SELECT COUNT(*) FROM att_project_user_rel WHERE project_id=? AND user_id=926 AND del_flag='0'",Integer.class,id));assertEquals("1",jdbc.queryForObject("SELECT valid_flag FROM att_project_user_rel WHERE project_id=? AND user_id=926 AND del_flag='0'",String.class,id));status.setRollbackOnly();});}
    @Test void callerCannotEditAnotherProjectOrReplaceItsCode(){actor(926);var input=request();input.setId(1L);assertThrows(AccessDeniedException.class,()->lifecycle.update(input));actor(925);input.setCode("wrong-code");assertThrows(AccessDeniedException.class,()->lifecycle.update(input));verifyNoInteractions(external);}
    @Test void invalidDefaultSchedulerFailsBeforeAnyExternalSideEffect(){ReflectionTestUtils.setField(lifecycle,"defaultScheduler","unknown");assertThrows(IllegalStateException.class,()->lifecycle.create(request()));verifyNoInteractions(sequence,external);}
    @Test void externalCreateFailureNeverCreatesLocalProject(){ReflectionTestUtils.setField(lifecycle,"defaultScheduler","DOLPHINSCHEDULER");when(external.saveProject(any())).thenReturn(externalResponse(1));long before=jdbc.queryForObject("SELECT COUNT(*) FROM att_project",Long.class);assertThrows(IllegalStateException.class,()->tx.execute(status->lifecycle.create(request())));assertEquals(before,jdbc.queryForObject("SELECT COUNT(*) FROM att_project",Long.class));verify(external,never()).deleteProject(anyLong());}
    @Test void externalCreateAndLocalOwnershipAreExplicit(){ReflectionTestUtils.setField(lifecycle,"defaultScheduler","DOLPHINSCHEDULER");when(external.saveProject(any())).thenReturn(externalResponse(0));tx.executeWithoutResult(status->{long id=lifecycle.create(request());assertEquals("DOLPHINSCHEDULER",jdbc.queryForObject("SELECT scheduler_type FROM att_project WHERE id=?",String.class,id));assertEquals("900900",jdbc.queryForObject("SELECT code FROM att_project WHERE id=?",String.class,id));verifyNoInteractions(sequence);status.setRollbackOnly();});}
    @Test void explicitExternalSchedulerCreatesMatchingProject(){when(external.saveProject(any())).thenReturn(externalResponse(0));tx.executeWithoutResult(status->{var input=request();input.setSchedulerType("DOLPHINSCHEDULER");long id=lifecycle.create(input);assertEquals("DOLPHINSCHEDULER",jdbc.queryForObject("SELECT scheduler_type FROM att_project WHERE id=?",String.class,id));assertEquals("900900",jdbc.queryForObject("SELECT code FROM att_project WHERE id=?",String.class,id));verify(external).saveProject(argThat(value->input.getName().equals(value.getProjectName())));verifyNoInteractions(sequence);status.setRollbackOnly();});}
    @Test void invalidRequestedSchedulerStopsBeforeExternalCall(){var input=request();input.setSchedulerType("unknown");assertThrows(IllegalArgumentException.class,()->lifecycle.create(input));verifyNoInteractions(sequence,external);}
    @Test void existingSchedulerCannotBeChangedOnEdit(){tx.executeWithoutResult(status->{long id=lifecycle.create(request());var input=request();input.setId(id);input.setSchedulerType("DOLPHINSCHEDULER");assertThrows(IllegalArgumentException.class,()->lifecycle.update(input));assertEquals("QUARTZ",jdbc.queryForObject("SELECT scheduler_type FROM att_project WHERE id=?",String.class,id));verifyNoInteractions(external);status.setRollbackOnly();});}
    @Test void externalUpdateFailureRollsBackLocalChangeAndNeverDeletesExistingProject(){String before=jdbc.queryForObject("SELECT name FROM att_project WHERE id=1",String.class);when(external.updateProject(any())).thenReturn(externalResponse(1));assertThrows(IllegalStateException.class,()->tx.execute(status->{jdbc.update("UPDATE att_project SET scheduler_type='DOLPHINSCHEDULER' WHERE id=1");var input=request();input.setId(1L);input.setName("must roll back");return lifecycle.update(input);}));assertEquals(before,jdbc.queryForObject("SELECT name FROM att_project WHERE id=1",String.class));verify(external,never()).deleteProject(anyLong());}
    @Test void invalidTemplateRollsBackProjectMemberAndRoleCreation(){long before=jdbc.queryForObject("SELECT COUNT(*) FROM att_project",Long.class);assertThrows(IllegalStateException.class,()->tx.execute(status->{jdbc.update("INSERT INTO system_role(role_id,project_id,role_name,role_key,role_sort,data_scope,status,del_flag) VALUES(900001,-1,'invalid template','admin',1,'5','0','0')");return lifecycle.create(request());}));assertEquals(before,jdbc.queryForObject("SELECT COUNT(*) FROM att_project",Long.class));assertEquals(0,jdbc.queryForObject("SELECT COUNT(*) FROM system_role WHERE role_id=900001",Integer.class));verifyNoInteractions(external);}
    @Test void externalProjectIsRetainedIfLocalTemplateBootstrapFails(){ReflectionTestUtils.setField(lifecycle,"defaultScheduler","DOLPHINSCHEDULER");when(external.saveProject(any())).thenReturn(externalResponse(0));assertThrows(IllegalStateException.class,()->tx.execute(status->{jdbc.update("INSERT INTO system_role(role_id,project_id,role_name,role_key,role_sort,data_scope,status,del_flag) VALUES(900001,-1,'invalid template','admin',1,'5','0','0')");return lifecycle.create(request());}));verify(external,never()).deleteProject(anyLong());assertEquals(0,jdbc.queryForObject("SELECT COUNT(*) FROM att_project WHERE code='900900'",Integer.class));}
    @Test void importCreationUsesTheSameMembershipAndCodeWorkflow(){
        var service=new tech.qiantong.qdata.module.att.service.project.impl.IAttProjectServiceImpl();var mapper=mock(tech.qiantong.qdata.module.att.dal.mapper.project.AttProjectMapper.class);ReflectionTestUtils.setField(service,"lifecycle",lifecycle);ReflectionTestUtils.setField(service,"attProjectMapper",mapper);
        tx.executeWithoutResult(status->{var row=new tech.qiantong.qdata.module.att.controller.admin.project.vo.AttProjectRespVO();row.setName("imported local project");row.setManagerId(925L);long before=jdbc.queryForObject("SELECT COUNT(*) FROM att_project",Long.class);service.importAttProject(List.of(row),false,"fixture");assertEquals(before+1,jdbc.queryForObject("SELECT COUNT(*) FROM att_project",Long.class));verify(mapper,never()).insert(any(tech.qiantong.qdata.module.att.dal.dataobject.project.AttProjectDO.class));verifyNoInteractions(external);status.setRollbackOnly();});
    }
    @Test void importUpdateCannotBypassStableProjectCode(){
        var service=new tech.qiantong.qdata.module.att.service.project.impl.IAttProjectServiceImpl();var mapper=mock(tech.qiantong.qdata.module.att.dal.mapper.project.AttProjectMapper.class);ReflectionTestUtils.setField(service,"lifecycle",lifecycle);ReflectionTestUtils.setField(service,"attProjectMapper",mapper);when(mapper.selectById(1L)).thenReturn(new tech.qiantong.qdata.module.att.dal.dataobject.project.AttProjectDO());var row=new tech.qiantong.qdata.module.att.controller.admin.project.vo.AttProjectRespVO();row.setId(1L);row.setName("forged import");row.setCode("foreign-code");assertThrows(tech.qiantong.qdata.common.exception.ServiceException.class,()->service.importAttProject(List.of(row),true,"fixture"));verify(mapper,never()).updateById(any(tech.qiantong.qdata.module.att.dal.dataobject.project.AttProjectDO.class));verifyNoInteractions(external);
    }

    @Test void repeatedProjectEditsDoNotDuplicateManagerRoleAssociation(){tx.executeWithoutResult(status->{long id=lifecycle.create(request());var input=request();input.setId(id);lifecycle.update(input);lifecycle.update(input);assertEquals(1,jdbc.queryForObject("SELECT COUNT(*) FROM system_user_role ur JOIN system_role r ON r.role_id=ur.role_id WHERE r.project_id=? AND ur.user_id=925",Integer.class,id));status.setRollbackOnly();});}
    @Test void projectMemberAndRoleAuditTimesUseTheApplicationInstant(){tx.executeWithoutResult(status->{var before=java.time.Instant.now();long id=lifecycle.create(request());var input=request();input.setId(id);lifecycle.update(input);for(String query:List.of("SELECT create_time FROM att_project WHERE id=?","SELECT update_time FROM att_project WHERE id=?","SELECT create_time FROM att_project_user_rel WHERE project_id=?","SELECT update_time FROM att_project_user_rel WHERE project_id=?","SELECT create_time FROM system_role WHERE project_id=?")){var timestamp=jdbc.queryForObject(query,java.sql.Timestamp.class,id);assertNotNull(timestamp);assertTrue(java.time.Duration.between(before,timestamp.toInstant()).abs().getSeconds()<5,"Audit time differs from application clock");}status.setRollbackOnly();});}

}
